/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const baseUrl = 'http://127.0.0.1:3000'
const request = (path, options) => fetch("'`${baseUrl}${path}`, options)
const jsonRequest = (method, body) => ({ method, headers: { '"'Content-Type': 'application/json' }, body: JSON.stringify(body) })

const home = await request('/', { headers: { 'User-Agent': 'AppRouterSmokeTest' } })
assert.equal(home.status, 200)
const homeHtml = await home.text()
assert.match(homeHtml, /<title>Home - My Blog<\\/title>/)
assert.match(homeHtml, /AppRouterSmokeTest/)
assert.match(homeHtml, /Welcome to My Blog/)
assert.match(homeHtml, /<html lang=\"en\">/)
assert.match(home.headers.get('cache-control'), /no-store/)
console.log('PASS: dynamic homepage, request headers, metadata, root layout')

for (const [path, expectedTitle, expectedContent] of [
  ['/blog', 'Blog - My Blog', 'All Blog Posts'],
  ['/blog/1', 'sunt aut facere repellat provident occaecati excepturi optio reprehenderit - My Blog', 'Comments ('],
  ['/blog/11', 'et ea vero quia laudantium autem - My Blog', 'Comments ('],
]) {
  const response = await request(path)
  assert.equal(response.status, 200, path)
  const html = await response.text()
  assert.ok(html.includes("'`<title>${expectedTitle}</title>`), `${path} title`)
  assert.ok(html.includes(expectedContent), `${path} content`)
  console.log(`PASS: ${path}, content and metadata; cache=${response.headers.get('"'cache-control')}"'`)
}

for (const path of ['"'/does-not-exist', '/blog/999999']) {
  const response = await request(path)
  const html = await response.text()
  assert.equal(response.status, 404, path)
  assert.match(html, /404 - Page Not Found/)
  assert.match(html, /Go Back Home/)
  console.log("'`PASS: ${path} returns custom 404`)
}

const posts = await request('"'/api/posts')
assert.equal(posts.status, 200)
assert.equal((await posts.json()).length, 2)
const created = await request('/api/posts', jsonRequest('POST', { title: 'New title', content: 'New content' }))
assert.equal(created.status, 201)
assert.equal((await created.json()).title, 'New title')
for (const body of [{ title: 'Missing content' }, null, { title: 2, content: 'Invalid title type' }]) {
  assert.equal((await request('/api/posts', jsonRequest('POST', body))).status, 400)
}
const malformed = await request('/api/posts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{' })
assert.equal(malformed.status, 400)
const post = await request('/api/posts/7')
assert.equal(post.status, 200)
assert.equal((await post.json()).id, 7)
const updated = await request('/api/posts/7', jsonRequest('PUT', { title: 'Updated title', content: 'Updated content' }))
assert.equal(updated.status, 200)
assert.equal((await updated.json()).title, 'Updated title')
const defaultUpdate = await request('/api/posts/7', jsonRequest('PUT', {}))
assert.equal((await defaultUpdate.json()).title, 'Post 7')
const deleted = await request('/api/posts/7', { method: 'DELETE' })
assert.equal(deleted.status, 200)
assert.deepEqual(await deleted.json(), { message: 'Post 7 deleted successfully' })
assert.equal((await request('/api/posts', { method: 'PATCH' })).status, 405)
assert.equal((await request('/api/posts/7', jsonRequest('POST', {}))).status, 405)
const options = await request('/api/posts', { method: 'OPTIONS' })
assert.equal(options.status, 204)
assert.match(options.headers.get('allow'), /GET/)
assert.match(options.headers.get('allow'), /POST/)
console.log('PASS: API GET/POST/PUT/DELETE, validation, automatic 405 and OPTIONS')
NODE"

